<script lang="ts">
 import {apiData} from '$lib/api';import {localization} from '$lib/localization';import {widgetText} from '$lib/widgets';
 import type {Employee} from '$lib/employees';import EmployeeDetailModal from '../EmployeeDetailModal.svelte';import DetailModal from '../DetailModal.svelte';import StatusNotice from '../StatusNotice.svelte';
 let {href,label}:{href:string;label:string}=$props();
 let t=$derived(widgetText[$localization.displayLanguage==='ja'?'ja':'en']);let detail=$derived(/^\/(employees|books)\/([1-9]\d*)$/.exec(href));
 let employee=$state<Employee|null>(null),book=$state<{name:string;author:string|null;publisher:string|null;isbn:string|null;sourceProvider:string|null;sourceUrl:string|null;sourceRetrievedAt:string|null;notes:string|null}|null>(null),loading=$state(false),error=$state('');let trigger=$state<HTMLElement|null>(null);
 async function open(event:MouseEvent){if(!detail)return;trigger=event.currentTarget as HTMLElement;loading=true;error='';try{const response=await fetch(`/v1/${detail[1]==='employees'?'employees':'book-titles'}/${detail[2]}`);if(!response.ok){error=response.status===403?t.denied:t.failed;return;}if(detail[1]==='employees')employee=await apiData<Employee>(response);else book=await apiData<typeof book>(response);}catch{error=t.failed;}finally{loading=false;}}
</script>
{#if detail}<button class="detail-link" disabled={loading} onclick={open}>{label}</button>{:else}<a {href}>{label}</a>{/if}
{#if error}<StatusNotice message={error} tone="error" onDismiss={()=>error=''}/>{/if}
{#if employee}<EmployeeDetailModal {employee} titleId="widget-employee-detail" returnFocus={trigger} onClose={()=>employee=null}/>{/if}
{#if book}<DetailModal title={book.name} titleId="widget-book-detail" closeLabel={$localization.displayLanguage==='ja'?'閉じる':'Close'} returnFocus={trigger} onClose={()=>book=null} compact><section class="app-detail-section"><dl class="app-detail-grid"><div><dt>{$localization.displayLanguage==='ja'?'著者':'Author'}</dt><dd>{book.author??'—'}</dd></div><div><dt>{$localization.displayLanguage==='ja'?'出版社':'Publisher'}</dt><dd>{book.publisher??'—'}</dd></div><div><dt>ISBN</dt><dd>{book.isbn??'—'}</dd></div>{#if book.sourceProvider==='openbd'&&book.sourceUrl&&book.sourceUrl.startsWith('https://')}<div class="app-detail-wide"><dt>{$localization.displayLanguage==='ja'?'出典':'Source'}</dt><dd>{book.sourceRetrievedAt?.slice(0,10)??''} · <a href={book.sourceUrl} target="_blank" rel="noopener noreferrer">{book.sourceUrl}</a></dd></div>{/if}</dl>{#if book.notes}<p class="app-detail-notes">{book.notes}</p>{/if}<a href="/books">{$localization.displayLanguage==='ja'?'書籍一覧':'Books'}</a></section></DetailModal>{/if}
<style>a,.detail-link{color:var(--action-primary);overflow-wrap:anywhere}.detail-link{font:inherit;text-align:left;text-decoration:underline;border:0;background:transparent;padding:0;min-height:44px;cursor:pointer}.detail-link:disabled{opacity:.5}</style>
